import csv
best={};need={};cat={};prio={}
with open('../inbox/06-09/设备申请.csv',encoding='utf-8-sig') as f:
    for r in csv.DictReader(f):
        c=r['案号'];k=(c,r['设备序号']);rev=int(r['修订号'])
        cat[c]=r['服务类别'];prio[c]=int(r['优先号'])
        if k not in best or rev>best[k][0]: best[k]=(rev,int(r['申请席位']),r['状态'])
for (c,dev),(rev,s,st) in best.items():
    if st.strip()=='取消': continue
    need[c]=need.get(c,0)+s
info={'T01':dict(obj='HZ-A',site='南站',cert='S32',lim='7个工作日',rule='按已生效专项条款执行（服务点验收通过后自第10日起才切换通用10个工作日，今日仍维持7个工作日）',mail='hz.new@office.test'),
      'T02':dict(obj='JL-B',site='西湾',cert='S21',lim='5个工作日',rule='按已生效专项条款执行（试点退出后自第10日起才改8个工作日，今日仍维持5个工作日）',mail='jl.new@office.test'),
      'T03':dict(obj='QH-A',site='南站',cert='S31',lim='10个工作日',rule='3个自然日建议未签批不生效，按六月通用10个工作日（切换待签）',mail='qh.service@office.test')}
rem={'东港':11-9,'西湾':9-7,'南站':10-6,'北仓':10-6}
print('结转余量',rem)
for c in sorted(need,key=lambda x:(prio[x],x)):
    d=info[c];S=d['site'];n=need[c]
    a=n if rem[S]>=n else 0
    rem[S]-=a
    d['alloc']=a
    txt=f"""# 六月版发布单 {c}

案号：{c}
对象：{d['obj']}
换机时限：{d['lim']}
服务类别：{cat[c]}
服务主站：{S}
服务凭证：{d['cert']}
预留席位：{a}

## 说明
- 本件为切换前最后一日按当日口径办理的新申请。
- 换机时限：{d['rule']}。
- 服务主站取今日（6月9日）有效签署单（第9日至第12日），服务凭证按主站＋{cat[c]}类别取用（含6月9日修订：西湾/送修→XW-91，本件类别不受影响）。
- 席位按真实结转余量（东港2/西湾2/南站4/北仓4，已扣除此前全部实占）核定：需求{n}席，{'足额预留'+str(a)+'席。' if a>0 else '余量不足，本批预留0席（有权受理，转候补）。'}
"""
    open(f'发布-{c}.md','w',encoding='utf-8').write(txt)
    print(c,d['obj'],d['lim'],S,d['cert'],'需求',n,'签',a)
print('余',rem)
